// ============ 実インシデント事例集と図解（公開事例から「仕組み・要因・対策」を学ぶ） ============
// 事例データ（GOVDOJO_INCIDENTS）・規格名（GOVDOJO_OWASP）・通知期限（GOVDOJO_CLOCKS）は上で定義。
const GOVINC_CAT = {
  inject: ["間接プロンプト注入・流出", "Indirect injection & exfiltration", "#E27069"],
  agent: ["エージェントの暴走・過剰権限", "Agent overreach", "#E28C4E"],
  supply: ["サプライチェーン", "Supply chain", "#D6B152"],
  abuse: ["AIを悪用した攻撃", "AI-enabled attacks", "#C08BE8"],
  exposure: ["設定不備・データ露出", "Misconfiguration & exposure", "#5FD3C2"],
  content: ["出力の害・当局の処分", "Output harms & enforcement", "#8FA8E8"],
};
const GOVINC_LAYERS = [["tech", ["技術", "Technical"]], ["proc", ["プロセス・運用", "Process"]], ["gov", ["ガバナンス・規程", "Governance"]]];
const GOVINC_BY_ID = Object.fromEntries(GOVDOJO_INCIDENTS.map((x) => [x.id, x]));

function GovOwaspChip({ code, en }) {
  const nm = GOVDOJO_OWASP[code];
  const col = code.startsWith("ASI") ? "#8FA8E8" : C.gold;
  return (
    <span style={{ fontSize: 10.5, color: col, border: `1px solid ${C.line}`, borderRadius: 5, padding: "1px 7px", lineHeight: 1.6 }}>
      <span style={{ fontFamily: "ui-monospace,monospace", fontWeight: 700 }}>{code}</span>{nm ? " " + nm[en ? 1 : 0] : ""}
    </span>
  );
}

function GovIncLink({ id, en, onOpen }) {
  const x = GOVINC_BY_ID[id];
  if (!x) return null;
  const col = (GOVINC_CAT[x.cat] || [])[2] || C.muted;
  return (
    <button onClick={() => onOpen && onOpen(id)} style={{ background: "transparent", border: `1px solid ${col}`, color: col, borderRadius: 999, padding: "2px 10px", fontSize: 11, cursor: "pointer", margin: "0 6px 6px 0" }}>
      {x.date.slice(0, 4)} {x.t[en ? 1 : 0]} →
    </button>
  );
}

// OWASP LLM Top 10 の版の対応（この道場は2025年版の番号。2026年版で番号が変わった）
